-- 131: Original BrillaPrep WASSCE Applied Electricity syllabus evidence beta questions, part 4.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_031', 'topic_was_elect_7', 'subj_wassce_elect_app', 'exam_wassce', 'What is the main property of a semiconductor diode?', 'multiple_choice', '["A. It amplifies without any bias or supply","B. It has zero resistance in both directions","C. It conducts readily in one direction and blocks in the other within ratings","D. It stores mechanical energy"]', 'C', 'A p-n junction diode permits forward current after its characteristic threshold and restricts reverse current until breakdown conditions. Therefore the correct answer is C: It conducts readily in one direction and blocks in the other within ratings.', 'easy', 1, 1, 90, 'st_was_elect_7', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_032', 'topic_was_elect_7', 'subj_wassce_elect_app', 'exam_wassce', 'What is the purpose of a rectifier?', 'multiple_choice', '["A. Increase mechanical speed","B. Convert DC into sound only","C. Measure insulation resistance","D. Convert alternating current into unidirectional current"]', 'D', 'Diodes arranged as half-wave or full-wave rectifiers steer alternating input so the load current has one principal direction. Therefore the correct answer is D: Convert alternating current into unidirectional current.', 'medium', 2, 2, 90, 'st_was_elect_7', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_033', 'topic_was_elect_7', 'subj_wassce_elect_app', 'exam_wassce', 'In a bipolar junction transistor, which terminal controls a much larger collector current?', 'multiple_choice', '["A. Base","B. Case","C. Heat sink","D. Insulator"]', 'A', 'A relatively small base current controls collector-emitter current in the active or switching operating regions of a BJT. Therefore the correct answer is A: Base.', 'hard', 1, 1, 90, 'st_was_elect_7', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_034', 'topic_was_elect_7', 'subj_wassce_elect_app', 'exam_wassce', 'What is the function of a smoothing capacitor after a rectifier?', 'multiple_choice', '["A. Increase ripple deliberately","B. Reduce ripple in the rectified output voltage","C. Block all direct current to the load","D. Create magnetic rotation"]', 'B', 'The capacitor charges near voltage peaks and releases energy between them, reducing variations in the unregulated DC output. Therefore the correct answer is B: Reduce ripple in the rectified output voltage.', 'easy', 2, 2, 90, 'st_was_elect_7', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_035', 'topic_was_elect_7', 'subj_wassce_elect_app', 'exam_wassce', 'What operating state is intended when a transistor is used as a closed electronic switch?', 'multiple_choice', '["A. Cut-off","B. Reverse breakdown","C. Saturation","D. Open-circuit bias only"]', 'C', 'In saturation the transistor conducts strongly with a small collector-emitter voltage, while cut-off represents the open-switch state. Therefore the correct answer is C: Saturation.', 'medium', 3, 3, 90, 'st_was_elect_7', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_036', 'topic_was_elect_8', 'subj_wassce_elect_app', 'exam_wassce', 'What is the main safety purpose of protective earthing?', 'multiple_choice', '["A. Make all conductors carry normal load current through earth","B. Increase touch voltage during a fault","C. Replace overcurrent protection","D. Provide a low-impedance fault path so protection disconnects exposed metal"]', 'D', 'Earthing connects exposed conductive parts so a fault current can operate protective devices quickly and limit dangerous touch voltage. Therefore the correct answer is D: Provide a low-impedance fault path so protection disconnects exposed metal.', 'hard', 2, 2, 90, 'st_was_elect_8', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_037', 'topic_was_elect_8', 'subj_wassce_elect_app', 'exam_wassce', 'What is the purpose of a fuse?', 'multiple_choice', '["A. Open the circuit when current exceeds its safe value for sufficient time","B. Maintain current regardless of faults","C. Increase conductor temperature","D. Act as a normal on-off control switch"]', 'A', 'A fuse element melts under excessive current, interrupting the circuit to reduce damage and fire risk when correctly rated and installed. Therefore the correct answer is A: Open the circuit when current exceeds its safe value for sufficient time.', 'easy', 1, 1, 90, 'st_was_elect_8', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_038', 'topic_was_elect_8', 'subj_wassce_elect_app', 'exam_wassce', 'Which device is designed to detect an imbalance between line and neutral currents?', 'multiple_choice', '["A. Energy meter","B. Residual current device","C. Step-up transformer","D. Series resistor"]', 'B', 'An RCD compares outgoing and returning current and disconnects when leakage exceeds its trip threshold, supplementing other protection. Therefore the correct answer is B: Residual current device.', 'medium', 2, 2, 90, 'st_was_elect_8', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_039', 'topic_was_elect_8', 'subj_wassce_elect_app', 'exam_wassce', 'Why is electrical power transmitted at high voltage?', 'multiple_choice', '["A. High voltage makes conductors have no resistance","B. It removes the need for insulation","C. Higher voltage permits lower current and lower I²R loss for the same power","D. It makes transformers unnecessary"]', 'C', 'For a given power, raising voltage lowers current, and resistive line loss falls with the square of current, subject to insulation and equipment requirements. Therefore the correct answer is C: Higher voltage permits lower current and lower I²R loss for the same power.', 'hard', 1, 1, 90, 'st_was_elect_8', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_040', 'topic_was_elect_8', 'subj_wassce_elect_app', 'exam_wassce', 'What nominal low-voltage supply is commonly delivered to a single-phase consumer from a 415/240 V distribution system?', 'multiple_choice', '["A. About 11 kV between phase and neutral","B. Exactly 0 V at the service terminals","C. About 132 kV inside the consumer unit","D. About 240 V between phase and neutral"]', 'D', 'A three-phase four-wire distribution system provides roughly 415 V phase-to-phase and 240 V phase-to-neutral for single-phase loads. Therefore the correct answer is D: About 240 V between phase and neutral.', 'easy', 3, 3, 90, 'st_was_elect_8', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to published WAEC Ghana Applied Electricity evidence; not official WAEC examination material.', 'https://waecgh.org/wp-content/uploads/2023/12/Technical17.pdf', 0, 1 FROM questions WHERE id BETWEEN 'q_was_elect_b001_031' AND 'q_was_elect_b001_040';
